 (int At,int Count) ArrayAt(int at,int stride){Bounds(at,ArraySize);int count=I(Data,at+P);uint cap=U(Data,at+P+4)&0x3fffffff;if(count<0||count>SkeletonImport.MaxBones||cap<count)throw new InvalidDataException(UiText.T("skeletonInvalid"));if(count==0)return(0,0);int p=Pointer(at);Bounds(p,(long)count*stride);return(p,count);}
