 public static Rig Read(byte[] bytes){Preflight(bytes);var p=new SkeletonPack();using var stream=new MemoryStream(bytes,false);p.DeserializePartially(new BinaryReaderEx(stream));var objects=p._dataSection._virtualMap.Values.Select(v=>(At:checked((int)v.Src),Class:p._classnames.OffsetClassNamesMap.TryGetValue(v.Dst,out var c)?c.ClassName:"")).ToArray();if(objects.Length>16384)throw new InvalidDataException(UiText.T("skeletonSize"));var rigs=new List<(int At,Rig Rig)>();foreach(var o in objects.Where(o=>o.Class=="hkaSkeleton")){
